mapper.select:
SELECT d.ID AS id, d.FLOW_DEFINITION_ID AS flowDefinitionId, d.VERSION AS version, d.DEPLOYED_GRAPH_JSON AS deployedGraphJson, d.IS_LATEST AS latest, d.ENV_CODE AS envCode, d.DELETED AS deleted, d.CREATE_USER AS createUser, d.CREATE_TIME AS createTime, d.UPDATE_USER AS updateUser, d.UPDATE_TIME AS updateTime FROM AST_FLOW_DEPLOYMENT d WHERE (d.DELETED = 0 OR d.DELETED IS NULL)
AND d.FLOW_DEFINITION_ID = #{req.flowDefinitionId}
AND d.VERSION = #{req.version}
AND d.IS_LATEST = #{req.latest}
AND d.ENV_CODE = #{req.envCode}
ORDER BY d.UPDATE_TIME DESC, d.ID DESC
